@startuml

class Patient {
  + Name : string
}

class Family {
  + Id : string
}

class Doctor {
  + Name : string
}

class Receptionist {}

class Nurse {}

class Appointment {
  + Date : date
  + Time : time
}

class Visit {
  + Diagnosis : string
  + Treatment : string
}

class Medication {
  + Name : string
}

class Prescription {
  + Date : date
}

Family "1" -- "*" Patient : contains
Family "1" -- "0..1" Doctor : has primary care physician
Patient "1" -- "*" Appointment : scheduled for
Patient "1" -- "*" Visit : undergoes
Appointment "1" -- "0..1" Visit : results in
Visit "1" -- "*" Medication : involves
Visit "1" -- "*" Prescription : results in

Receptionist "1" -- "*" Patient : registers
Receptionist "1" -- "*" Appointment : schedules
Nurse "1" -- "*" Visit : records
Nurse "1" -- "*" Prescription : records
Doctor "1" -- "*" Visit : performs
Doctor "1" -- "*" Prescription : prescribes
Doctor "1" -- "*" Appointment : sees

@enduml

